/**
 * Popular-name reference lists used by the lookalike rule. Generated by bench/pkgguard/06-export-reference.ts:
 *  - npm: the 2,000 most-downloaded names (weekly downloads from the npm search API) in the benchmark crawl, with any
 *    name reported malicious in OSV removed;
 *  - pypi: the authored well-known list, existence-checked on PyPI (no PyPI download source was reachable).
 * The file records its provenance; the lists are data, the matching thresholds live in names.ts.
 */
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import type { Ecosystem } from './installs.js';

let cache: { npm: string[]; pypi: string[]; provenance: Record<string, string> } | null = null;
function load() {
  if (!cache) cache = JSON.parse(readFileSync(join(dirname(fileURLToPath(import.meta.url)), 'reference-lists.json'), 'utf8'));
  return cache!;
}
export const referenceList = (eco: Ecosystem): string[] => load()[eco];
export const referenceProvenance = () => load().provenance;
